// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address a, uint256 amount, uint256 withdrawBefore) public {
        // a is an address whose userBalance we will check; it may or may not be the caller.
        // amount is added to the caller's balance; withdrawBefore controls whether a withdraws before the addition.
        vm.assume(a != address(0));
        vm.assume(a != address(this));

        // Fund a
        vm.deal(a, 0);

        // Record a's initial balance in the contract
        uint256 initialBalance = c.getBalance(a);
        uint256 ethSentToA = 0;

        // a may withdraw its balance before the addToBalance call
        if (withdrawBefore % 2 == 1 && initialBalance > 0) {
            vm.prank(a);
            c.withdrawBalance();
            ethSentToA += initialBalance;
            // after withdrawal, userBalance[a] should be 0
            initialBalance = 0;
        }

        // Now call addToBalance, possibly from a or from another address
        address caller = address(uint160(uint256(keccak256(abi.encode(a, amount)))) | 0x1000000000000000000000000000000000000000);
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();

        // After the call, a's userBalance is its initial (post-withdrawal) balance plus any amount if caller == a
        uint256 expectedBalance = initialBalance;
        if (caller == a) {
            expectedBalance += amount;
        }
        uint256 actualBalance = c.getBalance(a);

        // If a withdraws everything now, it should receive exactly its userBalance
        vm.prank(a);
        try c.withdrawBalance() { } catch { }
        uint256 finalBalance = c.getBalance(a);
        assertTrue(finalBalance == 0);

        // The invariant: after full withdrawal, a's userBalance is zero, meaning it couldn't have
        // lost any Ether due to overflow (bug would cause mismatch between expected and actual).
        // If overflow occurred, actualBalance would be less than expectedBalance, and a would
        // be unable to withdraw the full expected amount, but the assertion above already
        // checks that a can completely drain its balance.
        // Additionally, we verify that a's balance was at least what it should minimally be:
        // it should be >= initialBalance if caller != a, or >= initialBalance + amount if caller == a.
        // Overflow reduces the balance, so this fails for the bug.
        assertTrue(actualBalance >= initialBalance + (caller == a ? amount : 0));
    }
}

