pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, address a) public {
        // amount is fuzzed as uint96 to ensure the pre-balance can be set to a high value near overflow
        // a is the caller, fuzzed to cover any address
        vm.assume(a != address(0) && a != address(this));
        // Set the pre-balance to a high value using addToBalance (which is safe in the reference)
        // First ensure the contract has enough ether to credit balances (we don't test withdraw)
        uint256 initialSupply = 1000 ether;
        vm.deal(address(c), initialSupply);

        // Set userBalance[a] to type(uint256).max - amount + 1 via a direct call?
        // We cannot set storage directly. Instead, we use the addToBalance function itself
        // to bring the balance close to overflow.
        // We need to get the balance to a point where adding 'amount' will overflow.
        // In the reference, the require prevents this, so no state change.
        // In the bug, it overflows.
        // To set up a balance close to overflow, we can repeatedly call addToBalance with huge amounts,
        // but we cannot bypass the require in the reference. Instead, we use a trick:
        // We cannot directly set a high balance without going through addToBalance, which would revert on overflow.
        // However, the contract's addToBalance does not restrict the caller; we can call it many times with large values
        // to build up the balance. But that requires many calls, and the fuzzer would need to do that.
        // The fuzzer can only execute the code we write in the test; we are not doing a sequence of calls.
        // We must arrange the scenario in a single transaction or within the test body.
        // Since we cannot call vm.store (rejected), we need an alternative.
        // Observation: The bug triggers when userBalance[msg.sender] + msg.value overflows.
        // To reach that, we need to set userBalance[a] to a value > type(uint256).max - amount.
        // We can do this by making a contract that calls addToBalance many times, but the test is limited.
        // Actually, we can use the fact that the test itself can make multiple calls to c.addToBalance
        // before the assertion, as long as it's within the test body. The test body can contain a loop
        // or multiple calls. The fuzzer provides the parameters, but we can use those parameters
        // to determine how many calls or how much to send. However, the fuzzer's 'amount' is a single value.
        // We can use 'amount' to do a series of steps.
        // A simpler approach: we can use the fuzzer to provide an 'a' and an 'amount' such that
        // we attempt to addToBalance with value = amount, after setting the balance to exactly
        // type(uint256).max - amount + 1. But how to set that balance?
        // We can use the contract's own balance and a helper that withdraws? No, withdraw only sends ether,
        // it doesn't increase balance.
        // We need to call addToBalance with a value that brings the balance to the desired point.
        // Since we control the contract's ether (by vm.deal), we can call addToBalance from any address
        // with a specific value. But we cannot make the balance arbitrarily large in one call because
        // the require prevents overflow.
        // We can make multiple calls from 'a' with large amounts until the balance is near overflow.
        // We can use a loop that runs until the balance reaches a certain threshold, but the gas might be high.
        // However, Foundry fuzz tests have a gas limit; we can do a few calls.
        // Actually, we can exploit the fact that the buggy version does not have the require, so it WILL overflow.
        // But we need to set up a pre-state where the overflow occurs.
        // We can do: we know the max uint256. We can calculate how much to add.
        // We need to call addToBalance with a value that, when added to the current balance, overflows.
        // To get the current balance high, we can call addToBalance with a huge value from 'a' in a prior transaction.
        // In the reference, that call would succeed as long as no overflow. So we can do:
        // 1. vm.deal(address(this), huge) and call c.addToBalance{value: huge}() from address(this) to fund the contract.
        // No, we need to increase userBalance[a]. So we must call from 'a'.
        // We can prank a and call addToBalance with a huge value. But the value must be less than the remaining space.
        // We can do this multiple times until the balance is high.
        // Since we have a fuzzed 'amount', we can set the balance to type(uint256).max - amount, but we need to know 'amount'.
        // Inside the test, we know 'amount' (the fuzzed parameter). We can compute desired balance = type(uint256).max - amount + 1.
        // Then we need to set userBalance[a] to that desired balance.
        // We can do this by first ensuring userBalance[a] is 0. Then we call addToBalance from 'a' with value = desiredBalance.
        // BUT that value would be huge, and we need the contract to have that much ether to credit. We can vm.deal(address(c), desiredBalance).
        // So we can do:
        // vm.deal(address(c), desiredBalance);
        // vm.prank(a);
        // c.addToBalance{value: desiredBalance}();
        // This sets userBalance[a] = desiredBalance.
        // Then we record the pre-balance.
        // Then we attempt to add 'amount' from 'a' again.
        // In the reference, this second addToBalance will revert because desiredBalance + amount overflows (since desiredBalance = max - amount + 1, sum = max+1 overflow).
        // In the bug, it will not revert and will wrap.
        // Then we check the post-balance and assert that it is > pre-balance.
        // That assertion will pass in reference because the second call reverts (no state change, post == pre, so post > pre is false)?? Wait.
        // If the call reverts in reference, the pre-balance remains unchanged. Our assertion "post > pre" would be false because post == pre.
        // So we need to handle the revert properly. We can wrap the second call in a try/catch.
        // In reference, it reverts, so we catch and set a flag. Then we assert something about the balance.
        // The property: After a successful addToBalance, balance increases. In reference, the second call is never successful (it reverts), so the property vacuously holds for all inputs? 
        // Actually, the property "For any address a and any uint amount, after a successful addToBalance call, the balance is greater" is trivially true for the reference because the second call never succeeds.
        // But is that a valid general rule? It is a property of the reference: every successful addToBalance increases the balance.
        // The buggy version violates it because a successful addToBalance can overflow and decrease the balance.
        // So we need to test: if the second call succeeds, then the balance must have increased.
        // In the reference, the second call never succeeds, so the implication holds. In the bug, it succeeds and the balance does NOT increase (it wraps), so the implication fails.
        // Therefore, we can assert: either the call reverts, or the post-balance > pre-balance.
        // Even better: we can assert that (success && post-balance > pre-balance) || !success.
        // But we need a single assertTrue. We can compute a boolean that is true if and only if the property holds.
        // Let's design:
        // 1. Compute targetPre = type(uint256).max - amount + 1;
        // 2. vm.deal(address(c), targetPre); // give contract enough ether
        // 3. vm.prank(a); c.addToBalance{value: targetPre}(); // sets balance to targetPre
        // 4. uint256 pre = c.getBalance(a);
        // 5. vm.deal(address(c), amount); // need to ensure contract has enough ether for the second call
        // 6. (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("addToBalance()")); // use low-level call to bypass revert and capture success
        // 7. uint256 post = c.getBalance(a);
        // 8. assertTrue(!success || post > pre);
        // This asserts that if the call succeeded, the balance increased.
        // In reference, success is false (because require reverts), so assertion is !false || (anything) => true. Passes.
        // In bug, success is true, and post = (pre + amount) % 2^256, which is (type(uint256).max + 1) % 2^256 = 0. So post = 0, pre is targetPre > 0, so post > pre is false. Assertion !true || false => false. Fails.
        // This works!

        vm.assume(amount > 0 && amount <= type(uint256).max); // ensure amount is valid
        uint256 targetPre;
        unchecked { targetPre = type(uint256).max - amount + 1; }
        // We need targetPre to not overflow when adding amount. In the first call, we set balance to targetPre, which is < max. That's safe.
        // But targetPre + amount = max + 1 overflow only in the second call.
        vm.deal(address(c), targetPre);
        vm.prank(a);
        c.addToBalance{value: targetPre}();
        uint256 pre = c.getBalance(a);

        // Now attempt the critical call
        vm.deal(address(c), amount);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("addToBalance()"));
        uint256 post = c.getBalance(a);

        assertTrue(!success || post > pre);
    }
}

