pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 withdrawAmount, uint256 reverterSalt) public {
        // Keep amounts realistic, wide domain
        initialBalance = bound(initialBalance, 0, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, type(uint128).max);
        // Deploy a reverter that will fail any external call
        Reverter reverter = new Reverter();
        // Give the reverter contract an initial balance on C
        vm.deal(address(reverter), initialBalance);
        vm.prank(address(reverter));
        c.addToBalance{value: initialBalance}();

        // Now the reverter tries to withdraw. Because its fallback reverts, the call will fail.
        // The reference contract (P) clears the balance BEFORE the call, so after failure the balance is 0.
        // The mutant (M) clears the balance AFTER the call, so after failure the balance remains unchanged.
        bool ok;
        // Reverter will call withdrawBalance, its fallback reverts, but the top-level tx does not revert
        // because the revert is caught inside the try/catch wrapper of the external call within withdrawBalance.
        vm.prank(address(reverter));
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // The rule: After withdrawBalance, regardless of success/failure, the caller's balance MUST be zero.
        // Reference P: always zero (passes).
        // Mutant M: nonzero if the call failed (fails).
        uint256 balanceAfter = c.getBalance(address(reverter));
        assertTrue(balanceAfter == 0);
    }
}

