pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.addToBalance{value: depositAmount}();

        uint256 balBefore = c.getBalance(actor);
        assertEq(balBefore, depositAmount);

        // Deploy adversarial callee that reverts, simulating a forced failure
        RevertingReceiver reverter = new RevertingReceiver();

        // Send enough ETH to the reverter so the exploit relies on the contract logic, not failure due to 0 balance
        vm.deal(address(reverter), 1 ether);

        // Fuzz the adversarial party by transferring the attacker's balance to the reverter?
        // The contract sends ETH to msg.sender. We need msg.sender to be the reverter.
        // But actor deposited the funds. We'll make the actor the reverter.
        // Instead, we'll set the actor to be the reverter from the start.
        // Re-guide: fuzz a separate caller who will trigger withdrawBalance via the reverter.
    }

    function testFuzz_property_final(uint256 depositAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        depositAmount = bound(depositAmount, 1, type(uint128).max);

        // Actor deposits
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.addToBalance{value: depositAmount}();

        // Deploy adversarial callee that always reverts on receiving ETH
        RevertingReceiver reverter = new RevertingReceiver();

        // Deposit into the reverter's balance inside C
        vm.deal(address(reverter), depositAmount);
        vm.prank(address(reverter));
        c.addToBalance{value: depositAmount}();

        // Now reverter has a balance in C. It will call withdrawBalance.
        // The contract sends ETH to msg.sender (reverter), which will revert.
        // In the reference, userBalance[reverter] is set to 0 before the call, so even if reverter reverts,
        // the balance becomes 0. In the mutant, the balance is cleared only after the call,
        // so if the call reverts, the balance remains unchanged.
        vm.prank(address(reverter));
        try c.withdrawBalance() {
            // The call succeeded (unlikely because reverter reverts)
            assertEq(c.getBalance(address(reverter)), 0);
        } catch {
            // The call reverted. Check the balance after revert.
            // Reference: balance is 0 (cleared before call)
            // Mutant: balance is still depositAmount (clear after call)
            assertEq(c.getBalance(address(reverter)), 0);
        }
    }
}

contract RevertingReceiver {
    fallback() external payable {
        revert("forced failure");
    }
}

