        assertTrue(!ok || balanceAfter == 0); // only meaningful assertion: if it reverted, balance must be unchanged.
        // Actually we need exactly one assertTrue that reads c and distinguishes.
        // Better: assertTrue(!ok ? balanceAfter == balanceBefore : true);
    }
}

