pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        // bound amount to avoid overflow and have enough for deposit
        amount = bound(amount, 1, type(uint128).max);
        vm.assume(actor != address(0) && actor != address(c));

        // Deploy adversarial callee that reverts on receiving Ether
        Reverter reverter = new Reverter();
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 balanceBefore = c.getBalance(actor);
        uint256 reverterBalanceBefore = address(reverter).balance;
        uint256 actorEthBefore = actor.balance;

        // Attempt withdrawal to the adversarial address, which will revert
        vm.prank(actor);
